Lemma ap_ro_intro : forall (LS : list (Z * Z)) (m0 m2 m' : mem) data datad w h wpl fr KI KF LSP ks lps ps pa parr ba barr,
  munch [(datad, datad + 4 * (wpl * h))] m2 m' -> wmono asegs m2 m' ->
  (datad + 4 * (wpl * h) <= 2147446784 \/ 17594333495296 <= datad) ->
  keeps_live LS m0 m2 ->
  (forall b k, In (b, k) LS -> datad + 4 * (wpl * h) <= b \/ b + k <= datad) ->
  (forall b k, In (b, k) LS -> arange b k) ->
  (forall b k, In (b, k) LS -> wr_at asegs m2 b k /\ acc asegs m2 b k) ->
  In (data, 4 * (wpl * h)) LS ->
  rw_cells asegs m2 (fr + 32) [C4 (Z_to_bv 64 w)] -> rw_cells asegs m2 (fr + 48) [C4 (Z_to_bv 64 h)] ->
  (fr + 64 <= datad \/ datad + 4 * (wpl * h) <= fr) ->
  chunk LS KI 1024 -> u32arr asegs m0 KI ks -> kidx_ok 10 ks -> chunk LS KF 1024 ->
  ls_obj LS m0 LSP lps ps -> length ps = 10%nat ->
  pixa_objn LS m0 pa 10 parr ba barr ps -> Forall (fun e => p_w (pe_v e) = w /\ p_h (pe_v e) = h) ps -> wpl = (w * 8 + 31) / 32 ->
